-- jmcd-embroidery-olympus (researched)
UPDATE businesses SET description = 'JMCD Embroidery is a specialist embroidery and printing business based in Olympus, Pretoria, working across embroidery, sublimation, engraving, DTF and UV DTF printing. These different techniques let the business brand a wide range of items, from fabric-based promotional and corporate wear through to harder surfaces suited to engraving or UV printing.

Work wear and corporate clothing form a core part of the business, with embroidery and DTF printing used to apply company logos and branding onto garments ordered in bulk for staff or promotional giveaways. Typical turnaround on an order runs two to three days, letting businesses plan branded clothing or promotional items around a reasonably quick production cycle rather than a long lead time. Companies in and around Pretoria needing branded work wear, corporate clothing or promotional items can draw on a business built around several different printing and embroidery techniques under one roof.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.jmcd.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'jmcd-embroidery-olympus' AND description = 'JMCD Embroidery is a specialist embroidery and printing business in Olympus offering embroidery, sublimation, engraving, DTF and UV DTF printing on promotional, corporate and work wear, with a typical turnaround of 2 to 3 days.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- juliebean-artisan-coffee-waterkloof (researched)
UPDATE businesses SET description = 'JulieBean Artisan Coffee is a coffee roastery and cafe on Lynnwood Road in Menlo Park, roasting its own beans in house rather than buying in pre-roasted stock. Single-origin beans, including Colombian, Guatemalan, Ethiopian and Brazilian, are available to buy by the bag alongside the cafe''s food and drink menu of chai lattes, toasted sandwiches and other cafe fare, all prepared on site.

The Lynnwood cafe doubles as the roastery itself, letting customers watch the barista and kitchen team at work rather than visiting a space with its roasting done elsewhere. Beyond the cafe, JulieBean On The Move brings a mobile coffee bar to weddings, corporate launches and private functions for hosts wanting a curated coffee service rather than a standard catering setup. The cafe opens Monday to Friday from 6am to 4pm and Saturdays from 7am to 2pm, serving Menlo Park and the wider Pretoria area.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.juliebean.co.za'), description_enriched_at = datetime('now') WHERE slug = 'juliebean-artisan-coffee-waterkloof' AND description = 'A coffee roastery and cafe on Lynnwood Road in Menlo Park where coffee is roasted onsite and every dish is crafted in-house, offering chai lattes, toasted sandwiches and other cafe fare alongside mobile coffee service.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
